module edge_detector (
  input      clk,
  input      rst,
  input      sig,
  output reg rise,
  output reg fall,
  output     any_edge
);
  reg sig_d;

  always @(posedge clk) begin
    if (rst) begin
      rise  <= 1'b0;
      fall  <= 1'b0;
      sig_d <= 1'b0;
    end else begin
      rise  <= sig & ~sig_d;
      fall  <= ~sig & sig_d;
      sig_d <= sig;
    end
  end

  assign any_edge = rise | fall;
endmodule

