module priority_encoder #(
  parameter N = 8
) (
  input      [N-1:0]         req,
  output reg [$clog2(N)-1:0] idx,
  output                     valid,
  output     [N-1:0]         onehot
);

  reg [N-1:0] onehot_reg;
  integer i;

  assign valid = |req;
  assign onehot = onehot_reg;

  always @* begin
    idx = 0;
    onehot_reg = {N{1'b0}};

    for (i = 0; i < N; i = i + 1) begin
      if (req[i]) begin
        idx = i;
        onehot_reg = ({N{1'b0}} | ({{(N-1){1'b0}}, 1'b1} << i));
      end
    end
  end

endmodule

