  output                 sout
);
  always @(posedge clk) begin
    if (rst)
      q <= 0;
    else if (load)
      q <= din;
    else if (shift_en) begin
      if (dir)
        q <= {sin, q[WIDTH-1:1]};
      else
        q <= {q[WIDTH-2:0], sin};
    end
  end

  assign sout = dir ? q[0] : q[WIDTH-1];
endmodule

