  reg [7:0] shreg;

  always @(posedge clk) begin
    if (rst) begin
      state   <= S_IDLE;
      tx      <= 1'b1;
      clk_cnt <= 0;
      bit_idx <= 0;
      shreg   <= 0;
      done    <= 1'b0;
    end else begin
      done <= 1'b0;
      case (state)
        S_IDLE: begin
          tx <= 1'b1;
          if (start) begin
            shreg   <= data;
            state   <= S_START;
            tx      <= 1'b0;
            clk_cnt <= 0;
          end
        end

        S_START: begin
          if (clk_cnt == CLKS_PER_BIT - 1) begin
            clk_cnt <= 0;
            bit_idx <= 0;
            state   <= S_DATA;
            tx      <= shreg[0];
          end else begin
            clk_cnt <= clk_cnt + 1;
          end
        end

        S_DATA: begin
          if (clk_cnt == CLKS_PER_BIT - 1) begin
            clk_cnt <= 0;
            if (bit_idx == 7) begin
              state <= S_STOP;
              tx    <= 1'b1;
            end else begin
              bit_idx <= bit_idx + 1;
              tx      <= shreg[bit_idx + 1];
            end
          end else begin
            clk_cnt <= clk_cnt + 1;
          end
        end

        S_STOP: begin
          if (clk_cnt == CLKS_PER_BIT - 1) begin
            clk_cnt <= 0;
            state   <= S_IDLE;
            tx      <= 1'b1;
            done    <= 1'b1;
          end else begin
            clk_cnt <= clk_cnt + 1;
          end
        end
      endcase
    end
  end

  assign busy = (state != S_IDLE);

endmodule
