  localparam S_START = 2'd1;
  localparam S_DATA  = 2'd2;
  localparam S_STOP  = 2'd3;

  reg [1:0] state;
  reg [$clog2(CLKS_PER_BIT)-1:0] clk_cnt;
  reg [2:0] bit_idx;
  reg [7:0] shreg;

  always @(posedge clk) begin
    if (rst) begin
      state   <= S_IDLE;
      tx      <= 1'b1;
      clk_cnt <= 0;
      bit_idx <= 0;
      shreg   <= 0;
      done    <= 1'b0;
