          end else
            clk_cnt <= clk_cnt + 1;

        S_STOP:
          if (clk_cnt == CLKS_PER_BIT - 1) begin
            clk_cnt <= 0;
            state   <= S_IDLE;
            tx      <= 1'b1;
            done    <= 1'b1;
          end else
            clk_cnt <= clk_cnt + 1;
      endcase
    end
  end

  assign busy = (state != S_IDLE);

