module pwm #(
  parameter WIDTH = 8
) (
  input              clk,
  input              rst,
  input              en,
  input  [WIDTH-1:0] period,
  input  [WIDTH-1:0] duty,
  output [WIDTH-1:0] cnt,
  output             out,
  output             wrap
);
