  always @(posedge clk) begin
    if (rst || !en)
      count <= 0;
    else if (last)
      count <= 0;
    else
      count <= count + 1;
  end

  assign cnt  = count;
  assign out  = en && (count < duty);
  assign wrap = en && last;
endmodule

