        S_START:
          if (clk_cnt == CLKS_PER_BIT - 1) begin
            clk_cnt <= 0;
            bit_idx <= 0;
            state   <= S_DATA;
            tx      <= shreg[0];
          end else
            clk_cnt <= clk_cnt + 1;
        S_DATA:
          if (clk_cnt == CLKS_PER_BIT - 1) begin
            clk_cnt <= 0;
            if (bit_idx == 7) begin
              state <= S_STOP;
              tx    <= 1'b1;
            end else begin
              bit_idx <= bit_idx + 1;
              tx      <= shreg[bit_idx + 1];
