module priority_encoder #(
  parameter N = 8
) (
  input      [N-1:0]         req,
  output reg [$clog2(N)-1:0] idx,
  output                     valid,
  output     [N-1:0]         onehot
);
  integer i;
  reg [N-1:0] onehot_int;

  always @(*) begin
    idx        = 0;
    onehot_int = {N{1'b0}};

    for (i = 0; i < N; i = i + 1) begin
      if (req[i]) begin
        idx        = i;
        onehot_int = {N{1'b0}};
        onehot_int[i] = 1'b1;
      end
    end
  end

  assign valid  = |req;
  assign onehot = onehot_int;
endmodule

