module priority_encoder #(
  parameter N = 8
) (
  input      [N-1:0]         req,
  output reg [$clog2(N)-1:0] idx,
  output                     valid,
  output     [N-1:0]         onehot
);
  integer i;
  reg [N-1:0] onehot_reg;

  always @(*) begin
    idx = 0;

    for (i = 0; i < N; i = i + 1)
      if (req[i])
        idx = i;

    onehot_reg = {N{1'b0}};
    if (|req)
      onehot_reg[idx] = 1'b1;
  end

  assign valid  = |req;
  assign onehot = onehot_reg;

endmodule

