  // Search starting just after the last winner, wrapping around.
  always @(*) begin
    found = 1'b0;
    pick  = 0;
    for (k = 1; k <= N; k = k + 1)
      if (!found && !rst && req[(last + k) % N]) begin
        found = 1'b1;
        pick  = (last + k) % N;
