module shift_reg #(
  parameter WIDTH = 8
) (
  input                  clk,
  input                  rst,
  input                  load,
  input      [WIDTH-1:0] din,
  input                  shift_en,
  input                  dir,
  input                  sin,
  output reg [WIDTH-1:0] q,
  output                 sout
);

  always @(posedge clk) begin
    if (rst) begin
      q <= {WIDTH{1'b0}};
    end else if (load) begin
      q <= din;
    end else if (shift_en) begin
      if (dir == 1'b0)
        q <= {q[WIDTH-2:0], sin};
      else
        q <= {sin, q[WIDTH-1:1]};
    end
  end

  assign sout = (dir == 1'b0) ? q[WIDTH-1] : q[0];

endmodule

