module alu #(
  parameter WIDTH = 8
) (
  input      [WIDTH-1:0] a,
  input      [WIDTH-1:0] b,
  input      [2:0]       op,
  output reg [WIDTH-1:0] y,
  output reg             carry,
  output                 zero
);
  always @(*) begin
    y = {WIDTH{1'b0}};
    carry = 1'b0;

    case (op)
      3'd0: begin
        {carry, y} = {1'b0, a} + {1'b0, b};
      end
      3'd1: begin
        y = a - b;
        carry = (a < b);
      end
      3'd2: begin
        y = a & b;
      end
      3'd3: begin
        y = a | b;
      end
      3'd4: begin
        y = a ^ b;
      end
      3'd5: begin
        y = a << 1;
        carry = a[WIDTH-1];
      end
      3'd6: begin
        y = a >> 1;
        carry = a[0];
      end
      3'd7: begin
        y = (a < b) ? 1'b1 : 1'b0;
      end
      default: begin
        y = {WIDTH{1'b0}};
        carry = 1'b0;
      end
    endcase
  end

  assign zero = (y == 0);
endmodule

