    if (rst) begin
      sig_d <= 1'b0;
      rise  <= 1'b0;
      fall  <= 1'b0;
    end else begin
      sig_d <= sig;
      rise  <= sig & ~sig_d;
      fall  <= ~sig & sig_d;
    end
  end

  assign any_edge = rise | fall;

endmodule

