module rr_arbiter #(
  parameter N = 4
) (
  input                      clk,
  input                      rst,
  input      [N-1:0]         req,
  output reg [N-1:0]         grant,
  output     [$clog2(N)-1:0] last_idx
);
  reg [$clog2(N)-1:0] last;
  reg [$clog2(N)-1:0] pick;
  reg                 found;
  reg [N-1:0]         next_grant;
  integer k;

  // Search starting just after the last winner, wrapping around.
  always @(*) begin
    found      = 1'b0;
    pick       = last;
    next_grant = {N{1'b0}};

    for (k = 1; k <= N; k = k + 1) begin
      if (!found && req[(last + k) % N]) begin
        found = 1'b1;
        pick  = (last + k) % N;
      end
    end

    if (found)
      next_grant[pick] = 1'b1;
  end

  always @(posedge clk) begin
    if (rst) begin
      grant <= {N{1'b0}};
      last  <= N - 1;
    end else begin
      grant <= next_grant;
      if (found)
        last <= pick;
    end
  end

  assign last_idx = last;

endmodule

